<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import * as inspectionApi from '@/api/inspection'
import * as equipmentApi from '@/api/equipment'

const points = ref([])
const auth = useAuthStore()
const items = ref([])
const equipments = ref([])
const selectedPointId = ref('')
const pointVisible = ref(false)
const itemVisible = ref(false)
const pointForm = reactive({ equipId: '', pointCode: '', pointName: '', location: '' })
const itemForm = reactive({ pointId: '', itemCode: '', itemName: '', checkMethod: '', valueType: 'TEXT', minValue: '', maxValue: '', unit: '', optionsJson: '', requiredPhoto: 0 })
async function load() {
  try {
    const [pointResponse, equipmentResponse] = await Promise.all([inspectionApi.getPoints(), equipmentApi.getEquipments({ pageNum: 1, pageSize: 200 })])
    points.value = pointResponse.data || []; equipments.value = equipmentResponse.data?.list || []
    if (selectedPointId.value) items.value = (await inspectionApi.getItems(selectedPointId.value)).data || []
  } catch (error) { ElMessage.error(error.message || '巡检配置加载失败') }
}
async function choosePoint() { items.value = selectedPointId.value ? ((await inspectionApi.getItems(selectedPointId.value)).data || []) : [] }
async function createPoint() { try { await inspectionApi.createPoint({ ...pointForm, equipId: Number(pointForm.equipId) }); ElMessage.success('巡检点位已创建'); Object.assign(pointForm, { equipId: '', pointCode: '', pointName: '', location: '' }); pointVisible.value = false; await load() } catch (error) { ElMessage.error(error.message || '点位创建失败') } }
async function createItem() { try { await inspectionApi.createItem({ ...itemForm, pointId: Number(itemForm.pointId), minValue: itemForm.minValue === '' ? null : itemForm.minValue, maxValue: itemForm.maxValue === '' ? null : itemForm.maxValue, requiredPhoto: Number(itemForm.requiredPhoto) }); ElMessage.success('检查项已创建'); itemVisible.value = false; selectedPointId.value = itemForm.pointId; await choosePoint() } catch (error) { ElMessage.error(error.message || '检查项创建失败') } }
onMounted(load)
</script>

<template>
  <div class="page-intro"><div><h2>巡检配置</h2><p>先配置设备点位和检查项，再由巡检计划引用点位生成任务快照。点位是“巡哪里”，检查项是“看什么、怎么判定”。</p></div><div class="intro-actions"><button v-if="auth.hasPermission('inspection:config:write')" class="secondary-button" type="button" @click="pointVisible = true">新增巡检点位</button><button v-if="auth.hasPermission('inspection:config:write')" class="primary-button compact-button" type="button" @click="itemVisible = true">新增检查项</button><button class="table-action" type="button" @click="load">刷新</button></div></div>
  <el-dialog v-model="pointVisible" title="新增巡检点位" width="560px" destroy-on-close><p class="dialog-tip">点位对应设备上的具体检查位置，例如“主轴轴承”“控制柜风扇”。点位编码建议使用设备编码加流水号。</p><form class="config-form dialog-form" @submit.prevent="createPoint"><label class="form-label">所属设备</label><el-select v-model="pointForm.equipId" class="full-control" filterable placeholder="选择要巡检的设备" required><el-option v-for="equipment in equipments" :key="equipment.id" :label="`${equipment.equipCode} · ${equipment.equipName}`" :value="equipment.id" /></el-select><label class="form-label">点位编码</label><input v-model="pointForm.pointCode" class="form-input" required placeholder="例如 P-EQ001-002" /><label class="form-label">点位名称</label><input v-model="pointForm.pointName" class="form-input" required placeholder="例如 主轴轴承" /><label class="form-label">位置说明</label><input v-model="pointForm.location" class="form-input" placeholder="例如 一号装配线东侧" /><div class="dialog-actions"><button class="secondary-button" type="button" @click="pointVisible = false">取消</button><button class="primary-button compact-button" type="submit">保存点位</button></div></form></el-dialog>
  <section class="soft-card table-card"><div class="toolbar"><select v-model="selectedPointId" class="form-input" @change="choosePoint"><option value="">选择点位查看检查项</option><option v-for="point in points" :key="point.id" :value="point.id">{{ point.pointCode }} · {{ point.pointName }}</option></select></div><table class="data-table"><thead><tr><th>点位编码</th><th>点位名称</th><th>设备</th><th>位置</th></tr></thead><tbody><tr v-for="point in points" :key="point.id"><td>{{ point.pointCode }}</td><td>{{ point.pointName }}</td><td>设备 #{{ point.equipId }}</td><td>{{ point.location || '—' }}</td></tr></tbody></table></section>
  <section class="soft-card panel"><div class="panel-heading"><div><h3>检查项清单</h3><span>选择点位后查看已有检查项</span></div></div><table v-if="selectedPointId" class="data-table"><thead><tr><th>编码</th><th>名称</th><th>类型</th><th>范围</th><th>照片</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{ item.itemCode }}</td><td>{{ item.itemName }}</td><td>{{ item.valueType }}</td><td>{{ item.minValue ?? '—' }} ~ {{ item.maxValue ?? '—' }}</td><td>{{ item.requiredPhoto === 1 ? '必拍' : '否' }}</td></tr></tbody></table><div v-else class="empty-note">请先在上方选择点位，再查看检查项。</div></section>
  <el-dialog v-model="itemVisible" title="新增检查项" width="700px" destroy-on-close><p class="dialog-tip">检查项描述巡检员要填写的内容。数值型检查项请填写上下限和单位；需要现场留证时勾选“必须拍照”。</p><form class="config-form dialog-form" @submit.prevent="createItem"><label class="form-label">所属点位</label><el-select v-model="itemForm.pointId" class="full-control" filterable placeholder="选择检查项归属点位" required><el-option v-for="point in points" :key="point.id" :label="`${point.pointCode} · ${point.pointName}`" :value="point.id" /></el-select><label class="form-label">检查项编码</label><input v-model="itemForm.itemCode" class="form-input" required placeholder="例如 ITEM-VIB-001" /><label class="form-label">检查项名称</label><input v-model="itemForm.itemName" class="form-input" required placeholder="例如 主轴振动值" /><label class="form-label">检查方法</label><input v-model="itemForm.checkMethod" class="form-input" placeholder="例如 红外测温、目视、读取仪表" /><label class="form-label">填写类型</label><select v-model="itemForm.valueType" class="form-input"><option value="TEXT">文本</option><option value="NUMBER">数值</option><option value="BOOLEAN">是/否</option></select><div class="form-grid"><div><label class="form-label">最小值</label><input v-model="itemForm.minValue" class="form-input" type="number" placeholder="数值型可填，例如 0" /></div><div><label class="form-label">最大值</label><input v-model="itemForm.maxValue" class="form-input" type="number" placeholder="数值型可填，例如 80" /></div><div><label class="form-label">单位</label><input v-model="itemForm.unit" class="form-input" placeholder="例如 ℃、MPa、mm" /></div><div><label class="form-label">照片要求</label><select v-model.number="itemForm.requiredPhoto" class="form-input"><option :value="0">非必拍</option><option :value="1">必须拍照</option></select></div></div><div class="dialog-actions"><button class="secondary-button" type="button" @click="itemVisible = false">取消</button><button class="primary-button compact-button" type="submit">保存检查项</button></div></form></el-dialog>
</template>

<style scoped>
.config-form { display: grid; grid-template-columns: repeat(5, minmax(140px, 1fr)); gap: 10px; align-items: center; }.compact-button { width: auto; padding: 0 18px; }.intro-actions { display: flex; align-items: center; gap: 10px; }.toolbar { display: flex; gap: 10px; margin-bottom: 14px; }.toolbar .form-input { max-width: 360px; }.full-control { width: 100%; }.dialog-form { display: grid; gap: 2px; }.dialog-form.config-form { grid-template-columns: 1fr; align-items: stretch; }.dialog-form.config-form .form-label { margin-top: 10px; }.dialog-tip { margin: -4px 0 16px; color: #789087; font-size: 13px; line-height: 1.7; }.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 4px 14px; }.dialog-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 18px; }.dialog-actions .primary-button { width: auto; }.secondary-button { width: auto; height: 42px; padding: 0 18px; border: 1px solid #cbd9ce; border-radius: 9px; background: #f7faf7; color: #335f4d; cursor: pointer; }:deep(.el-dialog__body) { max-height: 70vh; overflow-y: auto; }@media (max-width: 600px) { .form-grid { grid-template-columns: 1fr; }.intro-actions { flex-wrap: wrap; } }
</style>
